// CSV stays in the browser; parsing rejects malformed input rather than guessing.
function parseCSV(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"'){if(field.trim())throw Error('Malformed quote');quoted=true;}else if(c===','){row.push(field);field='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Unclosed quote');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;}
const norm=s=>s.replace(/^\ufeff/,'').trim().toLowerCase().replace(/[^a-z0-9]/g,'');
function parseDate(raw){const s=raw.trim();let m=s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);if(!m)return null;let d=Number(m[1]),mo=Number(m[2]),y=Number(m[3]);let dt=new Date(Date.UTC(y,mo-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()===mo-1&&dt.getUTCDate()===d?dt:null;}
let imported=[];
const csvFile=document.getElementById('csv-file'),csvMessage=document.getElementById('csv-message'),csvRows=document.getElementById('csv-rows'),csvRowsB=document.getElementById('csv-rows-b');
function message(en,mr){csvMessage.textContent=document.documentElement.lang==='mr'?mr:en;}
csvFile.addEventListener('change',async()=>{imported=[];csvRows.replaceChildren();csvRowsB.replaceChildren();document.getElementById('csv-results').hidden=true;let f=csvFile.files[0];if(!f)return;if(f.size>5*1024*1024){message('File is larger than 5 MB. Please choose a smaller CSV.','फाइल ५ MB पेक्षा मोठी आहे. लहान CSV निवडा.');return;}
 try{const rows=parseCSV(await f.text());if(rows.length<2)throw Error('Empty file');const keys=rows[0].map(norm),find=(...names)=>keys.findIndex(x=>names.includes(x));const indexes={state:find('state'),district:find('district'),market:find('market'),commodity:find('commodity'),variety:find('variety'),grade:find('grade'),date:find('arrivaldate','date'),price:find('modalprice')};if(['state','district','market','commodity','date','price'].some(k=>indexes[k]<0))throw Error('Missing columns');
 imported=rows.slice(1).map(row=>{const val=k=>indexes[k]<0?'':(row[indexes[k]]||'').trim();return {state:val('state'),district:val('district'),market:val('market'),crop:val('commodity'),variety:val('variety'),grade:val('grade'),date:val('date'),dt:parseDate(val('date')),price:Number(val('price').replace(/,/g,'')),rawPrice:val('price')};}).filter(x=>x.state.toLowerCase()==='maharashtra'&&x.district.toLowerCase()==='nashik'&&x.crop.toLowerCase()==='onion'&&x.market&&x.dt&&x.rawPrice&&Number.isFinite(x.price)&&x.price>=0).sort((a,b)=>b.dt-a.dt).slice(0,100);
 if(!imported.length){message('No valid Nashik onion records found. Check the file and date format (DD/MM/YYYY).','नाशिक कांद्याच्या वैध नोंदी सापडल्या नाहीत. फाइल आणि दिनांक तपासा.');return;}
 imported.forEach((r,i)=>{const option=document.createElement('option');option.value=String(i);option.textContent=`${r.date} · ${r.market} · ${r.variety||'variety unknown'} · ${r.grade||'grade unknown'} · ₹${r.price}/q`;csvRows.append(option);csvRowsB.append(option.cloneNode(true));});if(imported.length>1)csvRowsB.selectedIndex=1;document.getElementById('csv-results').hidden=false;message(`${imported.length} matching rows shown, newest first. Verify the source, units, variety and report dates. This file is not automatically updated.`,`${imported.length} नोंदी दाखवल्या आहेत. स्रोत, एकक आणि दिनांक तपासा. फाइल आपोआप अद्ययावत होत नाही.`);
 }catch(e){message('Could not read this CSV. Required columns: State, District, Market, Commodity, Arrival_Date, Modal_Price. Dates must be DD/MM/YYYY.','CSV वाचता आली नाही. आवश्यक स्तंभ आणि DD/MM/YYYY दिनांक तपासा.');}
});
document.getElementById('csv-load').addEventListener('click',()=>{const selected=[imported[Number(csvRows.value)],imported[Number(csvRowsB.value)]];if(!selected[0]||!selected[1]||csvRows.value===csvRowsB.value){message('Choose two different records.','दोन वेगवेगळ्या नोंदी निवडा.');return;}let [a,b]=selected;if(a.market.toLowerCase()===b.market.toLowerCase()){message('Choose two different markets.','दोन वेगवेगळे बाजार निवडा.');return;}if(a.dt.getTime()!==b.dt.getTime()){message('Choose records reported on the same date.','समान दिनांकाच्या नोंदी निवडा.');return;}if(a.dt.getTime()>Date.now()){message('A report date is in the future. Check the file.','नोंदीतील तारीख भविष्यातील आहे. फाइल तपासा.');return;}if(a.variety.toLowerCase()!==b.variety.toLowerCase()||a.grade.toLowerCase()!==b.grade.toLowerCase()||!a.variety||!a.grade){message('Choose two records with the same known variety and grade for a meaningful comparison.','तुलनेसाठी समान ज्ञात प्रकार आणि दर्जाच्या दोन नोंदी निवडा.');return;}
 document.getElementById('crop').value=`${a.crop} · ${a.variety} · ${a.grade}`;for(const [i,k] of ['A','B'].entries()){document.getElementById('name'+k).value=`${selected[i].market} (${selected[i].date})`;document.getElementById('price'+k).value=String(selected[i].price);document.getElementById('transport'+k).value='';document.getElementById('other'+k).value='0';}document.getElementById('comparison').dispatchEvent(new Event('input',{bubbles:true}));message('Loaded. Enter transport costs and verify the reporting date, source and price units.','नोंदी भरल्या. वाहतूक खर्च भरा आणि तारीख, स्रोत व एकक तपासा.');document.getElementById('compare').scrollIntoView({block:'start'});
});
